import {test,expect} from 'vitest'
import {choose} from './subject.mts'
test('typed true', () => {
  const input = true
  const actual = choose(input)
  expect(actual).toBe(1)
})
test('typed false', () => {
  const input = false
  const actual = choose(input)
  expect(actual).toBe(0)
})

